// Offline support: dist/sw.js is generated by `npm run build:web` (workbox-config.js). A new version
// waits until Kindway restarts; the app offers to restart sooner. Kept out of index.html so the
// Content-Security-Policy (public/_headers) can forbid inline scripts.
if ('serviceWorker' in navigator) {
  window.addEventListener('load', function () {
    navigator.serviceWorker.register('/sw.js').catch(function () {});
  });
}
